 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # The seed object is a contiguous three-cell line; other non-background
    # cells identify positions where that line should be copied.
    candidates = []
    for r in range(h):
        for c in range(w):
            if c + 2 < w:
                vals = tuple(grid[r][c + i] for i in range(3))
                if all(v != bg for v in vals):
                    candidates.append((r, c, 0, 1, vals))
            if r + 2 < h:
                vals = tuple(grid[r + i][c] for i in range(3))
                if all(v != bg for v in vals):
                    candidates.append((r, c, 1, 0, vals))
    if not candidates:
        raise ValueError('No three-cell seed object found')

    # Select the seed whose cells are the rarest as a group, avoiding
    # accidental runs of the more common marker color.
    def seed_score(candidate):
        vals = candidate[4]
        return (sum(counts[v] for v in vals), max(counts[v] for v in vals))
    r0, c0, dr, dc, vals = min(candidates, key=seed_score)
    seed_cells = {(r0 + i * dr, c0 + i * dc) for i in range(3)}

    marker_counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                            if grid[r][c] != bg and (r, c) not in seed_cells)
    marker = marker_counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker and (r, c) not in seed_cells:
                for i, value in enumerate(vals):
                    rr = r + (i - 1) * dr
                    cc = c + (i - 1) * dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = value
    return out
